// Узел «Действие»: нажатие кнопки или ответ на черновик -> решение в журнал.
// «Опубликовать» ставит пост в очередь, «Отклонить» пишет причину, «Переписать»
// готовит промпт для нейросети под площадку PLATFORM. Команды не из чата редактора не выполняются.
// src/filter.js (вклеено scripts/build-workflows.js, править в src/)
const filterLib = (() => {
  const module = { exports: {} };
// Отбор новостей перед нейросетью: ключевые слова и отсев повторов.
// Файл без зависимостей: функции можно вставить в узел Code n8n целиком.
'use strict';

const TRACKING = /^(utm_\w+|fbclid|gclid|yclid|ref|from)$/i;

// Приводит текст к виду для сравнения: нижний регистр, ё -> е, только буквы и цифры.
function normalizeText(s) {
  return String(s || '')
    .toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .trim();
}

function tokens(s) {
  const t = normalizeText(s);
  return t ? t.split(' ') : [];
}

// Одна и та же статья по разным ссылкам: без схемы, www, якоря, меток utm и
// конечной косой черты. Нечитаемая ссылка возвращается как есть после trim.
function normalizeUrl(url) {
  const raw = String(url || '').trim();
  if (!raw) return '';
  const u = splitUrl(raw);
  if (!u) return raw.toLowerCase();
  const params = u.params
    .filter(([k]) => !TRACKING.test(k))
    .sort(([a], [b]) => a.localeCompare(b));
  const query = params.length ? '?' + params.map(([k, v]) => formEncode(k) + '=' + formEncode(v)).join('&') : '';
  const host = u.hostname.toLowerCase().replace(/^www\./, '');
  const p = u.pathname.replace(/\/+$/, '');
  return host + p + query;
}

// Кодирование как у URLSearchParams.toString(): пробел как +, остальное через %.
function formEncode(s) {
  return encodeURIComponent(s)
    .replace(/[!'()~]/g, (c) => '%' + c.charCodeAt(0).toString(16).toUpperCase())
    .replace(/%20/g, '+');
}

function formDecode(s) {
  const t = s.replace(/\+/g, ' ');
  try {
    return decodeURIComponent(t);
  } catch {
    return t;
  }
}

// Части ссылки: { hostname, pathname, params: [[ключ, значение]] } или null.
// В узлах Code n8n 2.x (отдельный процесс task runner) глобального URL нет,
// тогда ссылка разбирается регулярным выражением.
function splitUrl(raw) {
  if (typeof URL === 'function') {
    let u;
    try {
      u = new URL(raw);
    } catch {
      return null;
    }
    return { hostname: u.hostname, pathname: u.pathname, params: [...u.searchParams.entries()] };
  }
  const m = /^[a-z][a-z0-9+.-]*:\/\/([^/?#\s]+)([^?#\s]*)(\?[^#\s]*)?(#\S*)?$/i.exec(raw);
  if (!m) return null;
  const hostname = m[1].replace(/^[^@]*@/, '').replace(/:\d*$/, '');
  if (!hostname) return null;
  const params = (m[3] || '')
    .slice(1)
    .split('&')
    .filter(Boolean)
    .map((pair) => {
      const i = pair.indexOf('=');
      return i < 0 ? [formDecode(pair), ''] : [formDecode(pair.slice(0, i)), formDecode(pair.slice(i + 1))];
    });
  // Как URL: буквы не из ASCII в пути кодируются через %.
  const pathname = (m[2] || '/').replace(/[^\x00-\x7f]+/g, (c) => encodeURIComponent(c));
  return { hostname, pathname, params };
}

// Ключевое слово из нескольких слов ищется как фраза, каждое слово как начало
// слова в тексте («нейросет» найдёт «нейросети»). Короткие слова до трёх букв
// ищутся только целиком, чтобы «ИИ» не находилось внутри других слов.
function keywordMatches(textTokens, keyword) {
  const kw = tokens(keyword);
  if (!kw.length) return false;
  for (let i = 0; i + kw.length <= textTokens.length; i++) {
    let ok = true;
    for (let j = 0; j < kw.length; j++) {
      const t = textTokens[i + j];
      const k = kw[j];
      if (k.length <= 3 ? t !== k : !t.startsWith(k)) {
        ok = false;
        break;
      }
    }
    if (ok) return true;
  }
  return false;
}

function findKeywords(text, keywords) {
  const tt = tokens(text);
  return (keywords || []).filter((k) => keywordMatches(tt, k));
}

// Похожесть заголовков: коэффициент Жаккара по множествам основ слов
// (первые stemLength букв). Грубо, но переживает разные окончания в русском.
function titleSimilarity(a, b, stemLength = 5) {
  const stem = (s) => new Set(tokens(s).map((t) => t.slice(0, stemLength)));
  const A = stem(a);
  const B = stem(b);
  if (!A.size || !B.size) return 0;
  let inter = 0;
  for (const x of A) if (B.has(x)) inter++;
  return inter / (A.size + B.size - inter);
}

// items: [{ title, link, description }]. seen: уже собранные раньше записи
// с теми же полями (из журнала). Возвращает принятые и отклонённые с причиной.
function filterItems(items, config = {}, seen = []) {
  const keywords = config.keywords || [];
  const exclude = config.exclude || [];
  const threshold = config.similarityThreshold ?? 0.6;
  const stemLength = config.stemLength ?? 5;

  const accepted = [];
  const rejected = [];
  const seenUrls = new Set(seen.map((s) => normalizeUrl(s.link)).filter(Boolean));
  const seenTitles = seen.map((s) => s.title).filter(Boolean);

  for (const item of items || []) {
    const title = String((item && item.title) || '').trim();
    const reject = (reason, extra = {}) => rejected.push({ ...item, reason, ...extra });

    if (!title) {
      reject('нет заголовка');
      continue;
    }
    const url = normalizeUrl(item.link);
    if (url && seenUrls.has(url)) {
      reject('повтор ссылки');
      continue;
    }
    const text = title + ' ' + (item.description || '');
    const bad = findKeywords(text, exclude);
    if (bad.length) {
      reject('стоп-слово', { matched: bad });
      continue;
    }
    const matched = findKeywords(text, keywords);
    if (keywords.length && !matched.length) {
      reject('нет ключевых слов');
      continue;
    }
    let dup = null;
    for (const t of seenTitles) {
      const sim = titleSimilarity(title, t, stemLength);
      if (sim >= threshold) {
        dup = { duplicateOf: t, similarity: Math.round(sim * 100) / 100 };
        break;
      }
    }
    if (dup) {
      reject('похожий заголовок', dup);
      continue;
    }
    accepted.push({ ...item, matched });
    if (url) seenUrls.add(url);
    seenTitles.push(title);
  }
  return { accepted, rejected };
}

if (typeof module !== 'undefined') {
  module.exports = { normalizeText, normalizeUrl, findKeywords, titleSimilarity, filterItems };
}
  return module.exports;
})();
// src/log.js (вклеено scripts/build-workflows.js, править в src/)
const logLib = (() => {
  const module = { exports: {} };
// Журнал конвейера в SQLite: что собрано, что отклонено и почему, что опубликовано.
// Работает с любым объектом базы, у которого есть exec(sql) и prepare(sql) с
// методами run/get/all: node:sqlite (DatabaseSync) или better-sqlite3.
'use strict';

const STATUSES = ['collected', 'queued', 'rejected', 'published'];

// Разрешённые переходы. queued: редактор нажал «Опубликовать», пост ждёт
// отправки в канал. Опубликованное не откатывается: если пост удалили из
// канала, это отдельное событие, его в журнал пишет человек.
const TRANSITIONS = {
  collected: ['queued', 'rejected', 'published'],
  queued: ['published', 'rejected'],
  rejected: ['collected'],
  published: [],
};

const SCHEMA = `
CREATE TABLE IF NOT EXISTS items (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  url_key TEXT NOT NULL UNIQUE,
  link TEXT NOT NULL,
  title TEXT NOT NULL,
  source TEXT,
  description TEXT,
  status TEXT NOT NULL CHECK (status IN ('collected', 'queued', 'rejected', 'published')),
  reason TEXT,
  relevance REAL,
  message_id TEXT,
  post TEXT,
  collected_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  queued_at TEXT,
  published_at TEXT
);
CREATE INDEX IF NOT EXISTS items_status ON items (status);
CREATE INDEX IF NOT EXISTS items_collected_at ON items (collected_at);
`;

function defaultNormalizeUrl() {
  try {
    return require('./filter.js').normalizeUrl;
  } catch {
    // В узле Code без filter.js: только trim и нижний регистр.
    return (u) => String(u || '').trim().toLowerCase();
  }
}

function createLog(db, options = {}) {
  if (!db || typeof db.exec !== 'function' || typeof db.prepare !== 'function') {
    throw new TypeError('нужен объект базы с exec и prepare');
  }
  const now = options.now || (() => new Date().toISOString());
  const normalizeUrl = options.normalizeUrl || defaultNormalizeUrl();

  const keyOf = (link) => {
    const key = normalizeUrl(link);
    if (!key) throw new Error('нет ссылки');
    return key;
  };

  const get = (key) => db.prepare('SELECT * FROM items WHERE url_key = ?').get(key) || null;

  // Журнал старой схемы (без статуса queued) переносится в новую таблицу с теми же записями.
  function init() {
    const old = db.prepare("SELECT sql FROM sqlite_master WHERE type = 'table' AND name = 'items'").get();
    if (old && !String(old.sql).includes("'queued'")) {
      const cols = db.prepare('PRAGMA table_info(items)').all().map((c) => c.name).join(', ');
      db.exec('BEGIN');
      try {
        db.exec('ALTER TABLE items RENAME TO items_old; DROP INDEX IF EXISTS items_status; DROP INDEX IF EXISTS items_collected_at;');
        db.exec(SCHEMA);
        db.exec(`INSERT INTO items (${cols}) SELECT ${cols} FROM items_old; DROP TABLE items_old;`);
        db.exec('COMMIT');
      } catch (e) {
        db.exec('ROLLBACK');
        throw e;
      }
    } else {
      db.exec(SCHEMA);
    }
    // Описание из ленты появилось в журнале позже: старым записям поле добавляется пустым,
    // для них проверка на совпадения при переписывании пропускается.
    const cols = db.prepare('PRAGMA table_info(items)').all().map((c) => c.name);
    if (!cols.includes('description')) db.exec('ALTER TABLE items ADD COLUMN description TEXT');
    // Части поста для Телеграма (src/card.js): заголовок обложки, рубрика, картинка, Телеграф.
    if (!cols.includes('card')) db.exec('ALTER TABLE items ADD COLUMN card TEXT');
  }

  // Новая запись или повтор уже известной ссылки. Повтор не создаёт строку и
  // не меняет статус: возвращает { added: false, item } с прежней записью.
  function collected(item) {
    const link = String((item && item.link) || '').trim();
    const title = String((item && item.title) || '').trim();
    if (!title) throw new Error('нет заголовка');
    const key = keyOf(link);
    const old = get(key);
    if (old) return { added: false, item: old };
    const t = now();
    const description = String(item.description || '').trim() || null;
    db.prepare(
      `INSERT INTO items (url_key, link, title, source, description, status, collected_at, updated_at)
       VALUES (?, ?, ?, ?, ?, 'collected', ?, ?)`
    ).run(key, link, title, item.source || null, description, t, t);
    return { added: true, item: get(key) };
  }

  function move(link, status, fields) {
    const key = keyOf(link);
    const old = get(key);
    if (!old) throw new Error(`нет в журнале: ${link}`);
    if (!TRANSITIONS[old.status].includes(status)) {
      throw new Error(`нельзя перейти из ${old.status} в ${status}`);
    }
    const t = now();
    db.prepare(
      `UPDATE items SET status = ?, reason = ?, relevance = ?, message_id = ?,
       queued_at = ?, published_at = ?, updated_at = ? WHERE url_key = ?`
    ).run(
      status,
      fields.reason ?? null,
      fields.relevance ?? old.relevance ?? null,
      fields.messageId ?? old.message_id ?? null,
      status === 'queued' ? t : status === 'published' ? old.queued_at ?? null : null,
      status === 'published' ? t : null,
      t,
      key
    );
    return get(key);
  }

  // Причина обязательна: журнал нужен, чтобы видеть, почему новость не прошла.
  function rejected(link, reason, extra = {}) {
    const r = String(reason || '').trim();
    if (!r) throw new Error('у отказа должна быть причина');
    return move(link, 'rejected', { reason: r, relevance: extra.relevance });
  }

  function published(link, messageId, extra = {}) {
    if (messageId === undefined || messageId === null || String(messageId).trim() === '') {
      throw new Error('нет номера сообщения в канале');
    }
    return move(link, 'published', { messageId: String(messageId), relevance: extra.relevance });
  }

  // Редактор нажал «Опубликовать»: пост с черновиком встаёт в очередь на отправку в канал.
  function queued(link) {
    const old = get(keyOf(link));
    if (old && !old.post) throw new Error('в очередь только с черновиком');
    return move(link, 'queued', {});
  }

  // Черновик поста от нейросети (HTML для Телеграма) для записи в статусе collected.
  // Статус не меняется: публикует редактор кнопкой в боте.
  function drafted(link, post, extra = {}) {
    const text = String(post ?? '').trim();
    if (!text) throw new Error('пустой черновик');
    const key = keyOf(link);
    const old = get(key);
    if (!old) throw new Error(`нет в журнале: ${link}`);
    if (old.status !== 'collected') throw new Error(`черновик только для collected, сейчас ${old.status}`);
    // extra.card: части поста строкой JSON; не передано, остаются прежние.
    db.prepare('UPDATE items SET post = ?, relevance = ?, card = ?, updated_at = ? WHERE url_key = ?').run(
      text,
      extra.relevance ?? old.relevance ?? null,
      extra.card ?? old.card ?? null,
      now(),
      key
    );
    return get(key);
  }

  // Запись по номеру: кнопки бота редактора передают номер, ссылка в 64 байта не влезает.
  function byId(id) {
    return db.prepare('SELECT * FROM items WHERE id = ?').get(Number(id)) || null;
  }

  // Редактор вернул отклонённое в работу («Переписать»).
  function reopen(link) {
    return move(link, 'collected', {});
  }

  // Записи за последние days дней в виде { link, title } для filterItems(items, config, seen).
  function seen(days = 14) {
    const since = new Date(Date.parse(now()) - days * 86400000).toISOString();
    return db
      .prepare('SELECT link, title FROM items WHERE collected_at >= ? ORDER BY id')
      .all(since)
      .map((r) => ({ link: r.link, title: r.title }));
  }

  // Сводка: сколько в каждом статусе и самые частые причины отказа.
  function stats() {
    const counts = { collected: 0, queued: 0, rejected: 0, published: 0 };
    for (const r of db.prepare('SELECT status, COUNT(*) AS n FROM items GROUP BY status').all()) {
      counts[r.status] = Number(r.n);
    }
    const reasons = db
      .prepare(
        `SELECT reason, COUNT(*) AS n FROM items WHERE status = 'rejected'
         GROUP BY reason ORDER BY n DESC, reason`
      )
      .all()
      .map((r) => ({ reason: r.reason, count: Number(r.n) }));
    return { ...counts, total: counts.collected + counts.queued + counts.rejected + counts.published, reasons };
  }

  return { init, collected, drafted, queued, rejected, published, reopen, seen, stats, byId, get: (link) => get(keyOf(link)) };
}

if (typeof module !== 'undefined') {
  module.exports = { SCHEMA, STATUSES, TRANSITIONS, createLog };
}
  return module.exports;
})();
// src/editor.js (вклеено scripts/build-workflows.js, править в src/)
const editorLib = (() => {
  const module = { exports: {} };
// Бот редактора: разбор нажатий кнопок и ответов на черновик, действие над журналом.
// Файл без зависимостей: вклеивается в узел Code n8n (src/nodes/editor-action.js).
//
// Кнопки под черновиком шлют pub:<номер>, rew:<номер>, rej:<номер>.
// Ответом (reply) на черновик редактор может написать пометку для переписывания,
// а текст, начатый с «отклонить:», отклоняет черновик с этой причиной.
'use strict';

const ACTIONS = { pub: 'publish', rew: 'rewrite', rej: 'reject' };
const CALLBACK = /^(pub|rew|rej):(\d+)$/;
const REJECT_REPLY = /^\s*(отклонить|отклонено|отказ)\s*[:.,-]?\s*/i;
const DEFAULT_NOTE = 'Перепиши иначе: другие формулировки, яснее и короче.';
const NOTE_LIMIT = 500;

function escapeHtml(s) {
  return String(s ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function short(s, limit) {
  const t = String(s ?? '').replace(/\s+/g, ' ').trim();
  return t.length <= limit ? t : t.slice(0, limit - 1).trimEnd() + '…';
}

// Номер записи из клавиатуры сообщения с черновиком.
function idFromKeyboard(markup) {
  const rows = (markup && markup.inline_keyboard) || [];
  for (const row of rows) {
    for (const b of row || []) {
      const m = String((b && b.callback_data) || '').match(CALLBACK);
      if (m) return Number(m[2]);
    }
  }
  return null;
}

// Обновление Телеграма -> команда редактора.
// kind: 'button' (нажатие), 'reply' (ответ на черновик), 'denied' (чужой чат), 'ignore'.
function parseUpdate(update, options = {}) {
  const editor = String(options.editorChatId ?? '').trim();
  const allowed = (chatId) => editor !== '' && String(chatId) === editor;
  const u = update || {};

  if (u.callback_query) {
    const q = u.callback_query;
    const msg = q.message || {};
    const chatId = msg.chat ? msg.chat.id : null;
    // photo: черновик с обложкой. Текст подписи не правится узлом Telegram n8n,
    // поэтому такое сообщение после решения заменяется новым (см. editor-action.js).
    const base = { callbackQueryId: String(q.id || ''), chatId, messageId: msg.message_id ?? null, photo: Boolean(msg.photo) };
    if (!allowed(chatId)) return { kind: 'denied', ...base };
    const m = String(q.data || '').match(CALLBACK);
    if (!m) return { kind: 'ignore', ...base };
    return { kind: 'button', action: ACTIONS[m[1]], id: Number(m[2]), note: '', ...base };
  }

  const msg = u.message;
  if (msg && msg.reply_to_message && typeof msg.text === 'string') {
    const chatId = msg.chat ? msg.chat.id : null;
    if (!allowed(chatId)) return { kind: 'ignore' };
    const id = idFromKeyboard(msg.reply_to_message.reply_markup);
    if (id === null) return { kind: 'ignore' };
    const base = { callbackQueryId: '', chatId, messageId: msg.reply_to_message.message_id, id, photo: Boolean(msg.reply_to_message.photo) };
    const text = msg.text.trim();
    if (REJECT_REPLY.test(text)) {
      return { kind: 'reply', action: 'reject', note: short(text.replace(REJECT_REPLY, ''), NOTE_LIMIT), ...base };
    }
    if (!text) return { kind: 'ignore' };
    return { kind: 'reply', action: 'rewrite', note: short(text, NOTE_LIMIT), ...base };
  }

  return { kind: 'ignore' };
}

const STATUS_ANSWER = {
  queued: 'Уже в очереди',
  published: 'Уже опубликовано',
  rejected: 'Уже отклонено',
};

// Черновик для сообщения редактору с parse_mode HTML: пост для Телеграма и MAX уже
// в разметке, пост для ВКонтакте простым текстом экранируется.
function showPost(post) {
  const s = String(post ?? '');
  return /<\/?[a-z][^>]*>/i.test(s) ? s : escapeHtml(s);
}

// Текст сообщения с черновиком после решения: строка о решении, затем пост.
// Строка не длиннее 64 знаков: столько оставляет под неё сборка поста.
function decided(line, post) {
  return `${escapeHtml(short(line, 64))}\n\n${showPost(post)}`;
}

// Выполняет команду над журналом (log из createLog). Возвращает
// { answer, editText, rewrite }: ответ на нажатие, новый текст сообщения с черновиком
// (пусто, если менять не нужно) и данные для переписывания (или null).
function applyAction(log, cmd) {
  const none = { answer: '', editText: '', rewrite: null };
  if (!cmd || cmd.kind === 'ignore') return { ...none, answer: cmd && cmd.callbackQueryId ? 'Неизвестная кнопка' : '' };
  if (cmd.kind === 'denied') return { ...none, answer: 'Нет доступа' };

  const item = log.byId(cmd.id);
  if (!item) return { ...none, answer: 'Черновик не найден' };
  if (item.status !== 'collected') return { ...none, answer: STATUS_ANSWER[item.status] || 'Уже решено' };
  if (!item.post) return { ...none, answer: 'У записи нет черновика' };

  if (cmd.action === 'publish') {
    log.queued(item.link);
    return { answer: 'Поставлено в очередь', editText: decided('В очереди на публикацию', item.post), rewrite: null };
  }
  if (cmd.action === 'reject') {
    const reason = cmd.note ? `редактор: ${cmd.note}` : 'отклонено редактором';
    log.rejected(item.link, reason);
    return { answer: 'Отклонено', editText: decided(`Отклонено (${reason})`, item.post), rewrite: null };
  }
  if (cmd.action === 'rewrite') {
    const note = cmd.note || DEFAULT_NOTE;
    return {
      answer: 'Отправлено на переписывание',
      editText: decided('Отправлено на переписывание', item.post),
      rewrite: { id: item.id, note },
    };
  }
