  const pct = (x) => `${Math.round(x * 100)}%`;
  let frag = result.fragment;
  if (frag.length > 60) frag = frag.slice(0, 59).trimEnd() + '…';
  return `Дословно из источника: ${pct(result.ratio)} (порог ${pct(max)}), например «${frag}»`;
