    const id = idFromKeyboard(msg.reply_to_message.reply_markup);
    if (id === null) return { kind: 'ignore' };
    const base = { callbackQueryId: '', chatId, messageId: msg.reply_to_message.message_id, id, photo: Boolean(msg.reply_to_message.photo) };
    const text = msg.text.trim();
    if (REJECT_REPLY.test(text)) {
      return { kind: 'reply', action: 'reject', note: short(text.replace(REJECT_REPLY, ''), NOTE_LIMIT), ...base };
    }
    if (!text) return { kind: 'ignore' };
    return { kind: 'reply', action: 'rewrite', note: short(text, NOTE_LIMIT), ...base };
  }

  return { kind: 'ignore' };
}

const STATUS_ANSWER = {
  queued: 'Уже в очереди',
  published: 'Уже опубликовано',
  rejected: 'Уже отклонено',
};

// Черновик для сообщения редактору с parse_mode HTML: пост для Телеграма и MAX уже
// в разметке, пост для ВКонтакте простым текстом экранируется.
function showPost(post) {
  const s = String(post ?? '');
  return /<\/?[a-z][^>]*>/i.test(s) ? s : escapeHtml(s);
}

// Текст сообщения с черновиком после решения: строка о решении, затем пост.
// Строка не длиннее 64 знаков: столько оставляет под неё сборка поста.
function decided(line, post) {
  return `${escapeHtml(short(line, 64))}\n\n${showPost(post)}`;
}

// Выполняет команду над журналом (log из createLog). Возвращает
// { answer, editText, rewrite }: ответ на нажатие, новый текст сообщения с черновиком
// (пусто, если менять не нужно) и данные для переписывания (или null).
function applyAction(log, cmd) {
  const none = { answer: '', editText: '', rewrite: null };
  if (!cmd || cmd.kind === 'ignore') return { ...none, answer: cmd && cmd.callbackQueryId ? 'Неизвестная кнопка' : '' };
  if (cmd.kind === 'denied') return { ...none, answer: 'Нет доступа' };

  const item = log.byId(cmd.id);
  if (!item) return { ...none, answer: 'Черновик не найден' };
  if (item.status !== 'collected') return { ...none, answer: STATUS_ANSWER[item.status] || 'Уже решено' };
  if (!item.post) return { ...none, answer: 'У записи нет черновика' };

  if (cmd.action === 'publish') {
    log.queued(item.link);
    return { answer: 'Поставлено в очередь', editText: decided('В очереди на публикацию', item.post), rewrite: null };
  }
  if (cmd.action === 'reject') {
    const reason = cmd.note ? `редактор: ${cmd.note}` : 'отклонено редактором';
    log.rejected(item.link, reason);
    return { answer: 'Отклонено', editText: decided(`Отклонено (${reason})`, item.post), rewrite: null };
  }
  if (cmd.action === 'rewrite') {
    const note = cmd.note || DEFAULT_NOTE;
    return {
      answer: 'Отправлено на переписывание',
      editText: decided('Отправлено на переписывание', item.post),
      rewrite: { id: item.id, note },
    };
  }
  return { ...none, answer: 'Неизвестная кнопка' };
}

function unescapeHtml(s) {
  return String(s ?? '')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&amp;/g, '&');
}

// Текст черновика без заголовка, строки источника и разметки: его видит нейросеть.
// Заголовок поста ВКонтакте идёт первой строкой без разметки, его узнаёт title.
function draftBody(post, title) {
  const parts = String(post ?? '').split('\n\n');
  const head = String(title ?? '').replace(/\s+/g, ' ').trim();
  if (parts.length > 1 && (/^<b>/.test(parts[0]) || (head && parts[0].trim() === head))) parts.shift();
  if (parts.length > 1 && /^Источник: /.test(parts[parts.length - 1])) parts.pop();
  return unescapeHtml(parts.join('\n\n').replace(/<[^>]*>/g, '')).trim();
}

if (typeof module !== 'undefined') {
  module.exports = { ACTIONS, DEFAULT_NOTE, parseUpdate, applyAction, draftBody, idFromKeyboard, showPost };
}
  return module.exports;
})();
// src/card.js (вклеено scripts/build-workflows.js, править в src/)
const cardLib = (() => {
  const module = { exports: {} };
// Части поста для Телеграма: страница Телеграфа с подробным пересказом,
// запрос обложки к сервису cover/ и хранение частей в журнале (поле card, JSON).
// Файл без зависимостей: вклеивается в узлы Code n8n.
'use strict';

// Подробный пересказ нужен только большой новости: статья не короче ARTICLE_MIN
// знаков, а пересказ не короче FULL_MIN. Иначе в посте остаётся только источник.
const ARTICLE_MIN = 1500;
const FULL_MIN = 600;

const CHANNEL = {
  name: 'Нейросети: главное за день',
  url: 'https://t.me/neiro_glav',
};

// Название, ссылка и короткое имя канала из «Настроек» (CHANNEL_NAME, CHANNEL_URL).
function channelOf(settings = {}) {
  const name = String(settings.CHANNEL_NAME ?? '').trim() || CHANNEL.name;
  const url = String(settings.CHANNEL_URL ?? '').trim() || CHANNEL.url;
  const m = /t\.me\/([A-Za-z0-9_]{4,})/.exec(url);
  return { name, url, handle: m ? '@' + m[1] : '' };
}

function needFull(card, article) {
  return Boolean(
    card && typeof card.full === 'string' && card.full.trim().length >= FULL_MIN && String(article || '').length >= ARTICLE_MIN
  );
}

// Тело запроса createPage Телеграфа (https://telegra.ph/api#createPage).
// Ключ access_token в учётных данных узла, здесь его нет.
function telegraphPage({ title, full, image, link, sourceName, channel }) {
  const ch = channel || CHANNEL;
  const paragraphs = String(full || '')
    .split(/\n{2,}|\n/)
    .map((p) => p.trim())
    .filter(Boolean);
  const content = [];
  if (image && /^https:\/\//i.test(image)) content.push({ tag: 'figure', children: [{ tag: 'img', attrs: { src: image } }] });
  for (const p of paragraphs) content.push({ tag: 'p', children: [p] });
  content.push({ tag: 'p', children: ['Источник: ', { tag: 'a', attrs: { href: link }, children: [sourceName || link] }] });
  content.push({ tag: 'p', children: [{ tag: 'a', attrs: { href: ch.url }, children: [ch.name] }] });
  return {
    title: String(title || '').slice(0, 256),
    author_name: String(ch.name).slice(0, 128),
    author_url: ch.url,
    content: JSON.stringify(content),
    return_content: false,
  };
}

// Ответ Телеграфа -> адрес страницы или ''.
function telegraphUrl(res) {
  const url = res && res.ok && res.result && res.result.url;
  return typeof url === 'string' && /^https:\/\/telegra\.ph\//.test(url) ? url : '';
}

// Тело запроса к сервису обложек (cover/server.js).
function coverRequest(card, channel) {
  const ch = channel || channelOf();
  return {
    title: card.title,
    tag: card.tag || '',
    image: card.image || '',
    channel: ch.name,
    handle: ch.handle,
  };
}

// Части поста из журнала: JSON в поле card или null у старых записей.
function readCard(raw) {
  if (!raw) return null;
  try {
    const c = JSON.parse(raw);
    return c && typeof c === 'object' && c.title ? c : null;
  } catch {
    return null;
  }
}

// В журнал без подробного пересказа: он уже на странице Телеграфа.
function storeCard(card) {
  const { emoji, tag, title, lead, points, image, telegraph } = card;
  return JSON.stringify({ emoji, tag, title, lead, points, image: image || '', telegraph: telegraph || '' });
}

if (typeof module !== 'undefined') {
  module.exports = { ARTICLE_MIN, FULL_MIN, CHANNEL, channelOf, needFull, telegraphPage, telegraphUrl, coverRequest, readCard, storeCard };
}
  return module.exports;
})();

const { DatabaseSync } = require('node:sqlite');
const settings = $('Настройки').first().json;
const platform = postLib.platformOf(settings);
const limit = { telegram: postLib.TELEGRAM_TEXT_LIMIT, vk: postLib.VK_TEXT_LIMIT, max: postLib.MAX_TEXT_LIMIT }[platform];
const overlapWords = Number(settings.OVERLAP_WORDS) || overlapLib.DEFAULT_WORDS;
const overlapMax = settings.OVERLAP_MAX ?? overlapLib.DEFAULT_MAX;
const channel = cardLib.channelOf(settings);
// Подпись к обложке: предел 1024, запас под строку о переписывании и пометку.
const RESERVE = 160;

const db = new DatabaseSync(settings.CF_DB_PATH);
try {
  const log = logLib.createLog(db, { normalizeUrl: filterLib.normalizeUrl });
  log.init();
  const out = [];
  $input.all().forEach((it, i) => {
    const action = $('Действие').itemMatching(i).json;
    const item = log.byId(action.id);
    if (!item || item.status !== 'collected') return;
    const content = it.json && it.json.choices && it.json.choices[0] && it.json.choices[0].message
      ? it.json.choices[0].message.content
      : null;
    let failure = null;
    let post = null;
    let note = '';
    let relevance = item.relevance;
    const oldCard = cardLib.readCard(item.card);
    let card = null;
    if (typeof content !== 'string') {
      failure = 'ошибка запроса к нейросети';
    } else if (oldCard) {
      // Пост по частям: заголовок, рубрика, картинка и Телеграф прежние, остальное новое.
      const r = parseLib.parseCardResponse(content, { minRelevance: 0, title: false });
      if (!r.ok) {
        failure = r.reason;
      } else {
        try {
          card = { ...oldCard, emoji: r.card.emoji, lead: r.card.lead, points: r.card.points };
          post = postLib.buildCardPost(
            { ...card, link: item.link, sourceName: item.source },
            { limit: postLib.TELEGRAM_CAPTION_LIMIT - RESERVE }
          );
          relevance = r.relevance;
          if (item.description) {
            const same = overlapLib.overlap(r.text, item.description, { words: overlapWords });
            note = overlapLib.overlapNote(same, { max: overlapMax });
          }
        } catch (e) {
          card = null;
          post = null;
          failure = 'пост не собран: ' + e.message;
        }
      }
    } else {
      // Порог не применяется: редактор уже решил, что новость нужна.
      const r = parseLib.parseModelResponse(content, { minRelevance: 0 });
      if (!r.ok) {
        failure = r.reason;
      } else {
        try {
          // Запас 200 знаков под строку о переписывании и пометку о совпадениях, как при сборе.
          post = postLib.buildPostFor(
            platform,
            { title: item.title, text: r.text, link: item.link, sourceName: item.source },
            { limit: limit - 200 }
          );
          relevance = r.relevance;
          if (item.description) {
            const same = overlapLib.overlap(r.text, item.description, { words: overlapWords });
            note = overlapLib.overlapNote(same, { max: overlapMax });
          }
        } catch (e) {
          failure = 'пост не собран: ' + e.message;
        }
      }
    }
    if (post) log.drafted(item.link, post.text, { relevance, card: card ? cardLib.storeCard(card) : undefined });
    const head = post
      ? `Переписано. Оценка нейросети: ${relevance}/10${post.truncated ? ', текст обрезан' : ''}`
      : `Не переписано (${failure})`;
    // Бот редактора шлёт с parse_mode HTML: пост ВКонтакте простым текстом экранируется.
    const editorText =
      `${postLib.escapeHtml(head.length > 64 ? head.slice(0, 63) + '…' : head)}` +
      `${note ? '\n' + note : ''}\n\n${editorLib.showPost(post ? post.text : item.post)}`;
    const shownCard = card || oldCard;
    out.push({
      json: {
        id: item.id,
        link: item.link,
        rewritten: Boolean(post),
        editorText,
        // Черновик с обложкой, если есть части поста и текст влезает в подпись.
        photo: Boolean(shownCard) && postLib.visibleLength(editorText) <= postLib.TELEGRAM_CAPTION_LIMIT,
        cover: shownCard ? cardLib.coverRequest(shownCard, channel) : null,
      },
      pairedItem: { item: i },
    });
  });
  return out;
} finally {
  db.close();
}
